"use client";
import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/separator";

const initialProfile = {
  avatar: null,
  name: "Dr. Jane Doe",
  specialization: "Cardiologist",
  contact: "+1 234 567 8901",
  email: "jane.doe@example.com",
  bio: "Experienced cardiologist with a passion for preventive care and patient education.",
  clinic: {
    name: "Heart Health Clinic",
    address: "123 Main St, Springfield",
    phone: "+1 234 567 8910",
  },
};

export default function DoctorProfilePage() {
  const [profile, setProfile] = useState(initialProfile);
  const [avatarUrl, setAvatarUrl] = useState(profile.avatar);
  const [uploading, setUploading] = useState(false);

  const handleChange = (field, value) => {
    setProfile((prev) => ({ ...prev, [field]: value }));
  };

  const handleClinicChange = (field, value) => {
    setProfile((prev) => ({ ...prev, clinic: { ...prev.clinic, [field]: value } }));
  };

  // Optional: Cloudinary upload prompt
  const handleAvatarUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    // Replace with your Cloudinary upload preset and cloud name
    const data = new FormData();
    data.append("file", file);
    data.append("upload_preset", "YOUR_UPLOAD_PRESET");
    const res = await fetch("https://api.cloudinary.com/v1_1/YOUR_CLOUD_NAME/image/upload", {
      method: "POST",
      body: data,
    });
    const result = await res.json();
    setAvatarUrl(result.secure_url);
    setProfile((prev) => ({ ...prev, avatar: result.secure_url }));
    setUploading(false);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Save logic here
    alert("Profile saved!");
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">Doctor Profile</h1>
      <Card className="p-6 shadow rounded-xl space-y-6">
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Personal Details */}
          <div>
            <h2 className="text-lg font-semibold mb-4">Personal Details</h2>
            <div className="flex items-center gap-6 mb-4">
              <div className="relative">
                <Avatar src={avatarUrl} name={profile.name} className="w-20 h-20" />
                <label className="absolute bottom-0 right-0 bg-white rounded-full shadow p-1 cursor-pointer border border-gray-200">
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={handleAvatarUpload}
                  />
                  <span className="text-xs">{uploading ? "Uploading..." : "Edit"}</span>
                </label>
              </div>
              <div className="flex-1 grid grid-cols-1 gap-4">
                <Input
                  label="Name"
                  value={profile.name}
                  onChange={(e) => handleChange("name", e.target.value)}
                  placeholder="Full Name"
                  required
                />
                <Input
                  label="Specialization"
                  value={profile.specialization}
                  onChange={(e) => handleChange("specialization", e.target.value)}
                  placeholder="Specialization"
                  required
                />
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Input
                label="Contact"
                value={profile.contact}
                onChange={(e) => handleChange("contact", e.target.value)}
                placeholder="Contact Number"
                required
              />
              <Input
                label="Email"
                value={profile.email}
                onChange={(e) => handleChange("email", e.target.value)}
                placeholder="Email"
                type="email"
                required
              />
            </div>
          </div>
          <Separator />
          {/* Bio/About */}
          <div>
            <h2 className="text-lg font-semibold mb-2">Bio / About</h2>
            <Textarea
              value={profile.bio}
              onChange={(e) => handleChange("bio", e.target.value)}
              placeholder="Write something about yourself..."
              rows={4}
              required
            />
          </div>
          <Separator />
          {/* Clinic Details (optional) */}
          <div>
            <h2 className="text-lg font-semibold mb-2">Clinic Details <span className="text-gray-400 text-xs">(optional)</span></h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Input
                label="Clinic Name"
                value={profile.clinic.name}
                onChange={(e) => handleClinicChange("name", e.target.value)}
                placeholder="Clinic Name"
              />
              <Input
                label="Clinic Phone"
                value={profile.clinic.phone}
                onChange={(e) => handleClinicChange("phone", e.target.value)}
                placeholder="Clinic Phone"
              />
            </div>
            <Input
              label="Clinic Address"
              value={profile.clinic.address}
              onChange={(e) => handleClinicChange("address", e.target.value)}
              placeholder="Clinic Address"
              className="mt-2"
            />
          </div>
          <Button type="submit" className="w-full rounded-lg mt-4">Save Changes</Button>
        </form>
      </Card>
    </div>
  );
} 